-- Growths — Escola Aurora · PARTE 4 de 4: imagens dos criativos (11 anúncios). Rode depois da parte 1. Pode rodar de novo.
update anuncios a set imagem_url = x.img from (values
('AD03 · Depoimento Carla · 6 meses · Reels','data:image/webp;base64,'),
('AD06 · Inglês em 20 min por dia · Estático','data:image/webp;base64,'),
('AD09 · Quiz · qual é o seu nível? · Carrossel','data:image/webp;base64,'),
('AD12 · 3 erros de quem estuda sozinho · Carrossel','data:image/webp;base64,'),
('AD15 · Método em 4 passos · Carrossel','data:image/webp;base64,'),
('AD18 · Antes e depois · áudio real · Reels','data:image/webp;base64,'),
('AD21 · Depoimentos em sequência · Carrossel','data:image/webp;base64,'),
('AD24 · Vídeo 45s · Trava na hora de falar · Vídeo','data:image/webp;base64,'),
('AD27 · Busca · curso de inglês online · Texto','data:image/webp;base64,'),
('AD30 · Professora reage a erros · Vertical','data:image/webp;base64,'),
('Perpétuo · Prova social','data:image/webp;base64,')
) x(nome, img), workspaces w
where w.nome = 'Escola Aurora' and a.workspace_id = w.id and a.nome = x.nome;
select count(*) filter (where a.imagem_url is not null) as anuncios_com_imagem, count(*) as anuncios from anuncios a join workspaces w on w.id = a.workspace_id where w.nome = 'Escola Aurora';
